-- K.O DIVINII Premium Portfolio
-- Database: ko_divinii_portfolio_v2
CREATE DATABASE IF NOT EXISTS ko_divinii_portfolio_v2 CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE ko_divinii_portfolio_v2;
CREATE TABLE IF NOT EXISTS admins (id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(80) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS profile (id INT AUTO_INCREMENT PRIMARY KEY, headline VARCHAR(180) NOT NULL DEFAULT 'Creative Developer', intro TEXT, about TEXT, email VARCHAR(180), phone VARCHAR(80), location VARCHAR(160));
CREATE TABLE IF NOT EXISTS projects (id INT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(180) NOT NULL, category VARCHAR(120), year VARCHAR(10), description TEXT, cover_image VARCHAR(255), project_url VARCHAR(255), folder_path VARCHAR(255), visual_label VARCHAR(80), is_featured TINYINT(1) DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS skills (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, proficiency TINYINT UNSIGNED DEFAULT 70, level VARCHAR(80), sort_order INT DEFAULT 0);
CREATE TABLE IF NOT EXISTS experience (id INT AUTO_INCREMENT PRIMARY KEY, role VARCHAR(180) NOT NULL, organization VARCHAR(180), start_date VARCHAR(30), end_date VARCHAR(30), description TEXT);

-- Default admin account (change this password before public hosting).

